// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Hukuk, vatandaşlık, demokrasi, insan hakları ve Türkiye'nin anayasal düzeni (zor).
const ozSocialscience4Zor = <(String, String, List<String>, String)>[
  ('Hem ahlak kuralı hem de hukuk kuralı olarak düzenlenmiş bir davranışa en uygun örnek hangisidir?', 'Başkasını öldürmemek', ['Misafire ikramda bulunmak', 'Bayramlarda büyükleri ziyaret etmek', 'Sofrada önce büyüklerin başlamasını beklemek'], 'Öldürmeme hem ahlaken emredilir hem de ceza kanunuyla yaptırıma bağlanmıştır. Diğerleri yalnızca görgü veya gelenek kapsamındadır.'),
  ('Hukuk kurallarının emredici kurallar ve tamamlayıcı (yedek) kurallar diye ayrılmasında esas alınan ölçüt nedir?', 'Tarafların iradeleriyle aksinin kararlaştırılıp kararlaştırılamayacağı', ['Kuralın yazılı ya da yazısız olması', 'Kuralı koyan organın yasama ya da yürütme olması', 'Kuralın kamu ya da özel kişilere uygulanması'], 'Emredici kuralların aksi sözleşmeyle kararlaştırılamaz; tamamlayıcı kurallar ise taraflar aksini öngörmediğinde devreye girer.'),
  ('Borcunu ödemeyen kişinin malının icra dairesince haczedilip satılarak alacaklıya ödeme yapılması hangi yaptırım türüdür?', 'Cebri icra', ['Ceza', 'İptal', 'Disiplin cezası'], 'Cebri icra, yükümlülüğünü kendiliğinden yerine getirmeyen kişiye bu yükümlülüğün devlet gücüyle zorla yerine getirtilmesidir.'),
  ('Hukuka aykırı bir idari işlemin idare mahkemesi kararıyla ortadan kaldırılması hangi yaptırımdır?', 'İptal', ['Tazminat', 'Ceza', 'Cebri icra'], 'İdari yargı, hukuka aykırı bulduğu idari işlemi iptal eder; böylece işlem geriye etkili olarak ortadan kalkar.'),
  ('Bir bakanlığın çıkardığı yönetmelikte, ilgili kanunda bulunmayan yeni bir yasak getirildiği iddia edilmektedir. Bu iddia en doğru biçimde hangi ilke açısından değerlendirilir?', 'Yönetmeliğin kanuna aykırı olamayacağı ilkesi', ['Kanunların geriye yürümezliği ilkesi', 'Masumiyet karinesi ilkesi', 'Yasama dokunulmazlığı ve sorumsuzluğu ilkesi'], 'Yönetmelikler kanunların uygulanmasını sağlamak için çıkarılır ve kanuna aykırı olamaz; kanunda dayanağı olmayan yeni yasak normlar hiyerarşisine aykırıdır.'),
  ('Suç sayılan eylemleri ve bunlara uygulanacak cezaları belirleyen hukuk dalının kamu hukukunda yer almasının temel nedeni nedir?', 'Cezalandırma yetkisinin yalnızca devlete ait olması', ['Ceza davalarının yalnızca yazılı yürütülmesi', 'Suç mağdurlarının hep kamu görevlisi olması', 'Cezaların taraflarca sözleşmeyle belirlenmesi'], 'Suç ve ceza ilişkisinde devlet egemenlik gücüyle taraftır; cezalandırma yetkisi kişilere değil devlete aittir.'),
  ('Henüz doğmamış bir çocuğun mirasçı olabilmesi Türk Medeni Kanunu\'nda hangi koşula bağlanmıştır?', 'Sağ olarak doğması', ['Ana rahmine düştüğü anda nüfusa yazılması', 'Babasının vasiyetname bırakması', 'Doğumdan sonra en az bir yıl yaşaması'], 'TMK m.28\'e göre çocuk, sağ doğmak koşuluyla ana rahmine düştüğü andan itibaren hak ehliyetine sahiptir.'),
  ('Türk Medeni Kanunu\'na göre evlenmeden önce yapılan evlenme vaadine ne ad verilir ve bu vaat evlenmeye zorlamak için dava hakkı verir mi?', 'Nişanlanma; evlenmeye zorlamak için dava hakkı vermez.', ['Nişanlanma; evlenme için dava hakkı verir.', 'Resmî nikâh; boşanma davası açtırır.', 'Mehir; tazminat davasını zorunlu kılar.'], 'TMK m.118 ve 119\'a göre nişanlanma evlenme vaadiyle kurulur, ancak nişanlılık evlenmeye zorlamak için dava hakkı vermez.'),
  ('Türk Medeni Kanunu\'nun 1926\'da kabul edilmesinin kadın hakları bakımından getirdiği en önemli değişiklik hangisidir?', 'Tek eşliliğin ve resmî nikâhın zorunlu hâle gelmesi', ['Kadınlara milletvekili seçilme hakkı tanınması', 'Kadınlara belediye seçimlerinde oy hakkı verilmesi', 'Zorunlu ilköğretimin kabul edilmesi'], 'Medeni Kanun çok eşliliği kaldırmış, resmî nikâhı ve boşanmada eşitliği getirmiştir. Siyasi haklar sonraki yıllarda ayrı düzenlemelerle tanınmıştır.'),
  ('Babası suç işleyen bir kişinin, babası yerine cezalandırılması hangi anayasal ilkeyle bağdaşmaz?', 'Ceza sorumluluğunun şahsiliği', ['Vergi ödevi', 'Seçme ve seçilme hakkı', 'Yasama sorumsuzluğu ve dokunulmazlık'], 'Anayasa m.38\'e göre ceza sorumluluğu şahsidir; kimse başkasının fiili nedeniyle cezalandırılamaz.'),
  ('Anayasa\'ya göre bütün mahkemelerin her türlü kararının gerekçeli yazılması zorunluluğu öncelikle hangi hakkın kullanılmasını mümkün kılar?', 'Karara karşı etkili biçimde kanun yoluna başvurma hakkı', ['Mülkiyet hakkı', 'Seyahat özgürlüğü', 'Dernek kurma hakkı ve sendikal örgütlenme hakkı'], 'Gerekçe, tarafların kararın dayanağını öğrenmesini ve üst mahkemeye itiraz edebilmesini sağlar (Anayasa m.141).'),
  ('Sayıştay\'ın Anayasa\'daki görevine en uygun tanım hangisidir?', 'Kamu kaynaklarının kullanımını TBMM adına denetlemek', ['Adli davalarda temyiz incelemesi yapmak', 'Kanunların anayasaya uygunluğunu denetlemek', 'Seçimlerin genel yönetimini yürütmek'], 'Anayasa m.160\'a göre Sayıştay, genel ve özel bütçeli idarelerin gelir, gider ve mallarını TBMM adına denetler.'),
  ('Bölge adliye mahkemelerinin kurulmasıyla Türk adli yargısında oluşturulan yapı hangisidir?', 'İlk derece, istinaf ve temyizden oluşan üç dereceli yargılama', ['Yalnız tek dereceli yargılama', 'İlk derece ve Anayasa Mahkemesinden oluşan iki dereceli yapı', 'Danıştay\'ın adli davalara bakması'], 'Bölge adliye mahkemeleri 2016\'da faaliyete başlayarak istinaf aşamasını oluşturmuş, böylece ilk derece, istinaf ve Yargıtay temyizi şeklinde üç dereceli sistem kurulmuştur.'),
  ('Bir vatandaş, yıllarca uygulanan bir kuralın önceden duyurulmadan ve geçiş süresi tanınmadan aniden değiştirilmesinden yakınıyor. Bu yakınma, hukuk devletinin hangi alt ilkesine dayanır?', 'Hukuki güvenlik ilkesi', ['Yerinden yönetim ilkesi', 'Kuvvetler birliği ilkesi', 'Yasama dokunulmazlığı'], 'Hukuki güvenlik, kişilerin hukuk düzenine güvenebilmesini, kuralların öngörülebilir olmasını ve kazanılmış hakların korunmasını gerektirir.'),
  ('Antik Atina demokrasisinin bugünkü demokrasi anlayışına göre en önemli eksikliği neydi?', 'Kadınlar, köleler ve yabancılar yurttaşlık haklarından yararlanamazdı.', ['Halk meclisinde hiç oylama yapılmazdı.', 'Yöneticiler yalnızca soydan gelen krallardı.', 'Yasalar yazılı değildi ve hiç uygulanmazdı.'], 'Atina\'da siyasal katılım yalnız erkek yurttaşlarla sınırlıydı; nüfusun büyük kesimi karar süreçlerinin dışındaydı.'),
  ('İsviçre\'nin bazı küçük kantonlarında vatandaşların meydanda toplanıp el kaldırarak oy kullandığı geleneksel meclis uygulaması hangi demokrasi türüne yakındır?', 'Doğrudan demokrasi', ['Temsilî demokrasi', 'Parlamenter monarşi', 'Meclis hükümeti'], 'Landsgemeinde denilen bu açık hava meclislerinde halk, temsilciye gerek kalmadan doğrudan karar verir.'),
  ('Bir ülkede seçimler düzenli yapılmasına karşın muhalefet partileri kapatılmakta, basın sansürlenmekte ve yargı hükümete bağlı çalışmaktadır. Bu ülke için en doğru değerlendirme hangisidir?', 'Seçimlerin varlığı, demokrasinin diğer koşulları olmadıkça yeterli değildir.', ['Seçim yapıldığı için tam bir demokrasidir.', 'Basın sansürü demokrasiyi güçlendirir.', 'Yargının hükümete bağlı olması hukuk devletinin gereğidir.'], 'Demokrasi; serbest seçimin yanında çoğulculuk, ifade özgürlüğü ve bağımsız yargıyı da gerektirir. Yalnız sandık, demokrasiyi tanımlamaya yetmez.'),
  ('Millî egemenlik ile halk egemenliği yaklaşımlarını ayıran temel nokta hangisidir?', 'Millî egemenlikte egemenlik bölünmez bir bütün olarak millete, halk egemenliğinde ise her yurttaşa pay olarak aittir.', ['Millî egemenlikte seçim yapılmaz, halk egemenliğinde yapılır.', 'Halk egemenliği yalnızca monarşilerde uygulanır.', 'Millî egemenlik, egemenliğin bir hanedana ait olmasıdır.'], 'Fransız anayasa geleneğinde millî egemenlik soyut millet kişiliğini, halk egemenliği ise Rousseau\'nun yaklaşımıyla her yurttaşın egemenlikten pay almasını esas alır.'),
  ('Seçmenlerin önce ikinci seçmenleri, ikinci seçmenlerin de milletvekillerini seçtiği sistem Türkiye\'de hangi düzenlemeyle sona ermiştir?', '1946 seçimlerinde tek dereceli seçime geçilmesi', ['1924 Anayasası\'nın ilk kabulü', '1961\'de Senato\'nun kurulması', '1982\'de seçim yaşının değiştirilmesi'], 'Türkiye\'de 1946 seçimleriyle iki dereceli sistem bırakılmış, seçmenler milletvekillerini doğrudan seçmeye başlamıştır.'),
  ('Çoğunluk sisteminin genel olarak siyasal sonuçlarından biri hangisidir?', 'İki partili yapıyı ve tek parti hükümetlerini kolaylaştırması', ['Çok sayıda küçük partinin meclise girmesini teşvik etmesi', 'Koalisyon hükümetlerini zorunlu kılması', 'Oyların tamamının sandalyeye dönüşmesini sağlaması'], 'Duverger\'nin gözlemine göre tek turlu çoğunluk sistemi iki partili yapıya eğilim yaratır; küçük partilerin oyları sandalyeye dönüşmez.'),
  ('Yüksek bir seçim barajına yöneltilen en yaygın eleştiri hangisidir?', 'Temsilde adaleti zayıflatarak çok sayıda oyu karşılıksız bırakması', ['Seçmenlerin oy kullanmasını yasaklaması', 'Seçimlerin gizli yapılmasını engellemesi', 'Seçim sonuçlarının sayılmasını imkânsız kılması'], 'Barajın altında kalan partilerin oyları sandalyeye dönüşmez; bu, toplumda var olan kesimlerin meclis dışında kalmasına yol açar.'),
  ('Seçmenlerin yalnızca kayıtlı oldukları yerde ve seçmen kütüğüne göre oy kullanmasının temel amacı nedir?', 'Mükerrer oy kullanılmasını önlemek', ['Seçmenlerin oy gizliliğini kaldırmak', 'Seçim barajını yükseltmek', 'Adayları seçmenler arasından kurayla belirlemek ve listeyi kapatmak'], 'Seçmen kütüğü, her seçmenin tek bir sandıkta ve bir kez oy kullanmasını sağlayarak eşit oy ilkesini korur.'),
  ('Başkanlık sisteminde başkanın meclisi feshedememesi ve meclisin de başkanı güvensizlikle düşürememesi hangi yaklaşımın sonucudur?', 'Kuvvetlerin sert (katı) ayrılığı', ['Kuvvetler birliği', 'Yumuşak kuvvetler ayrılığı', 'Meclisin üstünlüğü ve yürütmenin meclis içinden çıkması'], 'Başkanlık sisteminde organlar birbirinin varlığına son veremez; ilişkiler veto ve onay gibi denge-denetim araçlarıyla yürür.'),
  ('John Locke\'un siyasal düşüncesinin modern insan hakları belgelerine en önemli katkısı hangisidir?', 'Yaşam, özgürlük ve mülkiyetin doğal haklar olduğu görüşü', ['Hükümdarın mutlak ve sınırsız egemenliği görüşü', 'Devletin kilise tarafından yönetilmesi gerektiği görüşü', 'Hukukun yalnızca güçlünün çıkarı olduğu görüşü'], 'Locke\'a göre devlet doğal hakları korumak için kurulur; bu fikir Amerikan Bağımsızlık Bildirgesi\'ne yansımıştır.'),
  ('Konfederasyonun federal devletten temel farkı nedir?', 'Konfederasyonu oluşturan devletler egemenliklerini korur ve birlik bir antlaşmaya dayanır.', ['Konfederasyon tek bir meclis ve tek yürütme organıyla yönetilir.', 'Konfederasyonda üye devletlerin ayrı anayasaları bulunamaz.', 'Konfederasyonun yalnız bir başkenti ve ortak ordusu vardır.'], 'Konfederasyon, egemen devletlerin uluslararası bir antlaşmayla kurduğu gevşek birliktir; federasyonda ise tek egemen devlet vardır.'),
  ('Devlet başkanının seçimle belirlendiği her yönetimin demokratik sayılamamasının nedeni nedir?', 'Cumhuriyet biçimi tek başına temel hak ve özgürlüklerin güvencesi değildir.', ['Cumhuriyetlerde hiç seçim yapılmaz.', 'Cumhuriyet ile monarşi aynı kavramdır.', 'Demokrasi yalnız monarşilerde görülür.'], 'Cumhuriyet devlet başkanlığının seçimle belirlenmesini anlatır; demokratik olması için çoğulculuk, serbest seçim ve hukuk devleti de gerekir.'),
  ('Sivil toplum kuruluşlarının güçlü olduğu bir ülkede demokrasinin işleyişi açısından en olası sonuç hangisidir?', 'Vatandaşların seçimler dışında da yönetimi etkileme kanallarının artması', ['Seçimlerin gereksiz hâle gelmesi', 'Siyasi partilerin kendiliğinden kapanması', 'Yargının görevlerinin derneklere devredilmesi'], 'Sivil toplum katılımı genişletir, yöneticiler üzerinde denetim oluşturur ve farklı kesimlerin sesini duyurmasını sağlar.'),
  ('İnsan haklarının bölünmezliği ilkesi en doğru biçimde nasıl açıklanır?', 'Hakların birbirine bağlı olup bir bütün olarak ele alınması gerektiği', ['Hakların yalnız devlet tarafından bölüştürülebileceği', 'Her hakkın yalnız bir kişiye ait olduğu', 'Hakların kuşaklara göre öncelik sırasıyla uygulanması gerektiği'], 'Medeni, siyasi, ekonomik ve sosyal haklar karşılıklı bağımlıdır; birinin ihlali diğerlerinin kullanımını da zayıflatır.'),
  ('Magna Carta ile 1789 İnsan ve Yurttaş Hakları Bildirgesi karşılaştırıldığında hangi fark öne çıkar?', 'Magna Carta belirli bir zümrenin haklarını, 1789 Bildirgesi ise tüm insanların haklarını esas alır.', ['Magna Carta evrensel, 1789 Bildirgesi yerel nitelik taşır.', 'İkisi de Birleşmiş Milletler tarafından hazırlanmıştır.', 'Magna Carta cumhuriyeti, 1789 Bildirgesi mutlak monarşiyi kurmuştur.'], 'Magna Carta esas olarak soyluların ayrıcalıklarını güvenceye alırken 1789 Bildirgesi hakları insan olmaya bağlayarak evrensel bir dil kullanmıştır.'),
  ('İnsan Hakları Evrensel Beyannamesi\'nin hukuki niteliğine ilişkin en doğru değerlendirme hangisidir?', 'Kabul edildiğinde bir tavsiye kararıydı; sonraki sözleşmeler hakları bağlayıcı hâle getirdi.', ['Kabul edildiği gün tüm devletler için cezai yaptırımlı bir antlaşmaydı.', 'Yalnız Avrupa ülkelerini bağlayan bölgesel bir sözleşmedir.', 'Hiçbir ülke tarafından desteklenmemiş, sonradan geri çekilmiştir.'], 'Beyanname Genel Kurul kararı olarak kabul edildi; 1966 tarihli iki uluslararası sözleşme ve bölgesel sözleşmeler hakları hukuken bağlayıcı kıldı.'),
  ('Birinci kuşak haklar ile ikinci kuşak haklar arasındaki temel fark devletin yükümlülüğü açısından nasıl açıklanır?', 'Birincisinde devletin müdahale etmemesi, ikincisinde ise hizmet sunması beklenir.', ['Birincisinde devlet hizmet sunar, ikincisinde müdahale etmez.', 'İkisinde de devletin hiçbir yükümlülüğü yoktur.', 'Her iki kuşakta da yalnızca uluslararası örgütler sorumludur.'], 'Kişisel haklar devlete karşı korunan özgürlük alanıdır; sosyal haklar ise devletin okul, hastane, sosyal güvenlik gibi olanaklar sağlamasını gerektirir.'),
  ('Kuşak sınıflandırmasına yöneltilen önemli bir eleştiri hangisidir?', 'Haklar arasında bir öncelik ya da önem sırası varmış izlenimi yaratması', ['Hakların tarihsel gelişimini hiç dikkate almaması', 'Yalnızca Asya ülkelerinin anayasalarına dayanması', 'Sosyal hakları tamamen yok sayması'], 'Kuşak ayrımı tarihsel bir sınıflamadır; ancak hakların bölünmezliği ilkesine göre kuşaklar arasında üstünlük sırası yoktur.'),
  ('Sağlık hakkının pozitif statü hakkı olarak sınıflandırılmasının nedeni nedir?', 'Hakkın gerçekleşmesi için devletin olumlu bir edimde bulunmasının gerekmesi', ['Devletin bu hakka hiç müdahale edememesi', 'Yalnızca seçimlerde kullanılabilmesi', 'Hakkın sadece kamu görevlilerine tanınmış olması'], 'Pozitif statü hakları istem haklarıdır; kişi devletten hastane, okul, sosyal güvenlik gibi hizmetler talep eder.'),
  ('Anayasa m.90\'a göre usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin uluslararası antlaşmalarla kanunların aynı konuda farklı hükümler içermesi hâlinde ne olur?', 'Uluslararası antlaşma hükümleri esas alınır.', ['Her zaman kanun hükmü uygulanır.', 'Uyuşmazlık TBMM\'de oylanarak çözülür.', 'İki düzenleme de kendiliğinden yürürlükten kalkar ve boşluk oluşur.'], '2004 değişikliğiyle m.90\'a eklenen cümleye göre temel haklara ilişkin antlaşmalarla kanunlar çatışırsa antlaşma hükümleri esas alınır.'),
  ('Çocuk işçiliğinin yasaklanması, Çocuk Haklarına Dair Sözleşme\'nin hangi temel hak grubunun parçası olarak değerlendirilir?', 'Koruma hakları', ['Katılım hakları', 'Siyasal haklar', 'Seçme ve seçilme hakları'], 'Sözleşme çocuğu ekonomik sömürüden, sağlığına ve eğitimine zarar verecek işlerden korumayı devletlere ödev olarak yükler.'),
  ('Türkiye\'de kadınlara milletvekilliği hakkının birçok Avrupa ülkesinden önce tanınmasının önemi nasıl değerlendirilir?', 'Cumhuriyetin eşitlik ilkesini siyasal alana taşıması', ['Kadınların askerlik yükümlülüğünden muaf tutulması', 'Medeni Kanun\'un yürürlükten kaldırılması', 'Seçimlerde oy gizliliğinin sona ermesi'], 'Fransa\'da 1944, İtalya\'da 1945\'te tanınan bu hak Türkiye\'de 1934\'te verilmiş; bu, cumhuriyetin çağdaşlaşma ve eşitlik hedefini yansıtır.'),
  ('Anayasa m.10\'a göre kadınlar ve erkekler için eşitliği sağlamaya yönelik devletin aldığı tedbirler hakkında hangisi doğrudur?', 'Eşitlik ilkesine aykırı olarak yorumlanamaz.', ['Eşitlik ilkesine aykırı sayılır ve iptal edilir.', 'Yalnız olağanüstü hallerde alınabilir.', 'Uygulanması için halk oylaması zorunludur.'], '2010 değişikliğiyle m.10\'a eklenen hükme göre kadın-erkek eşitliği için alınacak tedbirler eşitlik ilkesine aykırı olarak yorumlanamaz.'),
  ('İfade özgürlüğünün demokratik toplum için neden vazgeçilmez kabul edildiğine ilişkin en uygun gerekçe hangisidir?', 'Kamusal tartışmayı ve yöneticilerin denetimini mümkün kılması', ['Hükümetin eleştirilmesini engellemesi', 'Basının yalnız resmî açıklamaları yayımlamasını sağlaması', 'Seçimlerin yapılmasını gereksiz kılması'], 'AİHM içtihadına göre ifade özgürlüğü yalnız kabul gören fikirleri değil, rahatsız edici ve şok edici fikirleri de korur; demokratik toplumun temelidir.'),
  ('Anayasa m.24\'e göre kimsenin ibadete, dinî ayin ve törenlere katılmaya, dinî inanç ve kanaatlerini açıklamaya zorlanamaması hangi anlayışın sonucudur?', 'Din ve vicdan özgürlüğünün laiklik ile güvenceye alınması', ['Devletin belirli bir mezhebi zorunlu kılması', 'Din eğitiminin tamamen yasaklanması', 'Dinî kuralların devlet düzenine temel yapılması'], 'Laik devlet, inanmayı ya da inanmamayı bireyin özgür iradesine bırakır; bu nedenle kimse inancını açıklamaya zorlanamaz.'),
  ('1876 Kanun-i Esasi\'ye göre Osmanlı\'daki yönetim biçimine ilişkin en doğru tespit hangisidir?', 'Meclis bulunmakla birlikte padişahın yetkileri geniş kalmıştır.', ['Padişahlık kaldırılmış, cumhuriyet kurulmuştur.', 'Egemenlik açıkça millete ait sayılmıştır.', 'Meclis, padişahı görevden alma yetkisine sahiptir.'], 'Kanun-i Esasi meşruti monarşiyi kurmuştur; ancak padişah meclisi açıp kapatma ve sürgün yetkisi gibi geniş yetkilerini korumuştur.'),
  ('1921 Teşkilat-ı Esasiye Kanunu\'nun benimsediği hükümet sistemi hangisidir ve bu tercihin nedeni nedir?', 'Meclis hükümeti; savaş koşullarında bütün yetkiyi TBMM\'de toplamak', ['Başkanlık sistemi; ABD\'yi örnek almak', 'Parlamenter monarşi; padişahın yetkilerini artırmak', 'Yarı başkanlık; güçlü bir devlet başkanı yaratmak'], '1921 Anayasası yasama ve yürütme yetkilerini TBMM\'de toplamış, bakanlar meclisçe tek tek seçilmiştir.'),
  ('1961 Anayasası\'nın TBMM\'yi Millet Meclisi ve Cumhuriyet Senatosu olarak iki meclisli yapmasının amacı en doğru nasıl açıklanır?', 'Yasama sürecini daha dikkatli kılarak çoğunluğun aceleci kararlarını dengelemek', ['Kanun yapımını tamamen durdurmak', 'Yürütmeyi yasamaya bağlı kılmak', 'Seçimleri ortadan kaldırmak'], 'İkinci meclis olan Senato, kanunların daha uzun bir süzgeçten geçmesini sağlayarak bir denge unsuru olarak düşünülmüştür.'),
  ('Aşağıdakilerden hangisi Anayasa\'nın değiştirilmesi teklif dahi edilemeyecek hükümleri arasında yer alır?', 'Türkiye Devletinin dilinin Türkçe olması', ['Milletvekili sayısı', 'Cumhurbaşkanının görev süresi', 'Seçimlerin kaç yılda bir yapılacağı'], 'Anayasa m.3 devletin ülkesi ve milletiyle bölünmez bütünlüğünü, dilinin Türkçe, bayrağının ve marşının, başkentinin Ankara olduğunu düzenler; m.4\'e göre değiştirilemez.'),
  ('Anayasa m.2\'deki "Başlangıçta belirtilen temel ilkelere dayanan" ifadesinin hukuki önemi nedir?', 'Başlangıç kısmının da Anayasa metnine dâhil ve bağlayıcı olduğunu göstermesi', ['Başlangıç kısmının yalnızca tarihsel bir açıklama olduğunu göstermesi', 'Başlangıç kısmının her yıl yeniden yazılmasını gerektirmesi', 'Başlangıç kısmının halk oylamasıyla kaldırıldığını göstermesi'], 'Anayasa m.176\'ya göre başlangıç kısmı Anayasa metnine dâhildir; m.2 ile de Cumhuriyetin nitelikleri bu ilkelere bağlanmıştır.'),
  ('Cumhuriyetin "demokratik devlet" niteliğinin hukuk devleti niteliğiyle ilişkisi en doğru nasıl açıklanır?', 'Çoğunluk iradesi hukukun ve temel hakların çizdiği sınırlar içinde kullanılır.', ['Demokratik çoğunluk, hukuk kurallarını aşabilecek tek güçtür.', 'Hukuk devleti ancak seçimsiz yönetimlerde var olabilir.', 'Demokratik devlet, yargı denetimini gerektirmez.'], 'Anayasal demokrasilerde seçilmiş çoğunluk dahi anayasaya ve temel haklara bağlıdır; bu bağı hukuk devleti kurar.'),
  ('Yasama dokunulmazlığını yasama sorumsuzluğundan ayıran temel özellik hangisidir?', 'Dokunulmazlık geçicidir ve Meclis kararıyla kaldırılabilir.', ['Dokunulmazlık kalıcıdır, hiçbir zaman kaldırılamaz.', 'Dokunulmazlık yalnız Meclis kürsüsündeki sözleri kapsar.', 'Dokunulmazlık yalnız Cumhurbaşkanına tanınmıştır.'], 'Yasama dokunulmazlığı milletvekilinin görevi süresince tutuklanıp yargılanmasını engelleyen geçici bir güvencedir; sorumsuzluk ise sürekli ve mutlaktır.'),
  ('Bir kanunun "yayımı tarihinde yürürlüğe girer" hükmü içermesi ile "yayımından altı ay sonra yürürlüğe girer" hükmü içermesi arasındaki farkın amacı ne olabilir?', 'Uygulayıcılara ve vatandaşlara uyum için hazırlık süresi tanımak', ['Kanunu halk oylamasına sunmak', 'Cumhurbaşkanının veto süresini uzatmak', 'Kanunu Anayasa Mahkemesinin denetiminden kaçırmak için bekletmek'], 'Yürürlüğün ertelenmesi, kapsamlı değişikliklere idarenin ve toplumun uyum sağlamasına imkân verir; bu hukuki güvenlik ilkesine de hizmet eder.'),
  ('2017 değişikliğinden sonra bütçe kanunu teklifini TBMM\'ye kim sunar?', 'Cumhurbaşkanı', ['Milletvekilleri', 'Sayıştay Başkanı', 'Hazine ve Maliye Bakanı ile Merkez Bankası Başkanı birlikte'], 'Anayasa m.161\'e göre Cumhurbaşkanı, merkezî yönetim bütçe kanunu teklifini mali yıl başından en az yetmiş beş gün önce TBMM\'ye sunar.'),
  ('2017 değişikliğinden sonra yürütme organının yapısındaki temel değişiklik hangisidir?', 'Yürütmenin tek başlı hâle gelmesi', ['Yürütmenin üç başlı hâle gelmesi', 'Başbakanın halk tarafından seçilmesi', 'Bakanların Meclis üyeleri arasından seçilme zorunluluğu getirilmesi'], 'Anayasa m.8\'e göre yürütme yetkisi ve görevi Cumhurbaşkanı tarafından kullanılır; başbakanlık kaldırıldığı için yürütme tek başlıdır.'),
  ('Cumhurbaşkanlığı kararnamelerine ilişkin hangi ifade 2017 değişikliğinden sonraki Anayasa\'ya uygundur?', 'Kanunlarda açıkça düzenlenen konularda çıkarılamaz.', ['Kanunlardan üstün kabul edilir.', 'Temel hakların tamamını düzenleyebilir.', 'Anayasa Mahkemesinin denetimine hiçbir şekilde tabi değildir ve iptal edilemez.'], 'Anayasa m.104\'e göre kanunlarda açıkça düzenlenen konularda kararname çıkarılamaz; kararname ile kanun çatışırsa kanun uygulanır.'),
  ('Bireysel başvuru yoluyla Anayasa Mahkemesine hangi iddia ile başvurulabilir?', 'Kamu gücünce, hem Anayasa\'da hem AİHS\'de güvence altındaki bir hakkın ihlal edildiği', ['Herhangi bir sözleşmeden doğan alacağın ödenmediği', 'Bir kanunun ekonomik açıdan yararsız olduğu', 'Komşunun gürültü yaptığı ve bu yüzden tazminat istendiği'], 'Anayasa m.148\'e göre herkes, Anayasa\'da güvence altına alınmış temel hak ve özgürlüklerinden AİHS kapsamındaki herhangi birinin kamu gücünce ihlal edildiği iddiasıyla başvurabilir.'),
  ('Anayasa Mahkemesinin bir kanun hükmünü iptal ederken yerine yeni bir düzenleme yapamamasının nedeni nedir?', 'Kanun koyucu gibi hareket ederek yasama yetkisini kullanamayacak olması', ['Mahkemenin yalnız ceza davalarına bakması', 'İptal kararlarının halk oylamasına bağlı olması', 'Yeni düzenlemenin her zaman Danıştay\'a ait olması ve bakanlıkça uygulanması'], 'Anayasa m.153\'e göre Anayasa Mahkemesi iptal kararı verirken kanun koyucu gibi hareketle yeni bir uygulamaya yol açacak biçimde hüküm tesis edemez.'),
  ('Hâkimlerin tarafsızlığı ile bağımsızlığı arasındaki farkı en iyi açıklayan ifade hangisidir?', 'Bağımsızlık dış baskıdan korunmayı, tarafsızlık taraflara eşit mesafede durmayı ifade eder.', ['Bağımsızlık ve tarafsızlık aynı şeydir; ikisi de hâkimin maaşıyla ilgilidir.', 'Tarafsızlık yalnız savcılar için, bağımsızlık yalnız avukatlar için geçerlidir.', 'Bağımsızlık hâkimin dilediği kanunu uygulamasıdır.'], 'Bağımsızlık yargının diğer güçlerden etkilenmemesi, tarafsızlık ise hâkimin davanın taraflarına karşı önyargısız olmasıdır; adil yargılanma ikisini birlikte gerektirir.'),
  ('Anayasa\'nın değiştirilmesinin olağan kanunlardan daha zor koşullara bağlanmasının sebebi nedir?', 'Anayasa\'nın üstünlüğünü ve istikrarını korumak', ['Kanun yapımını tümüyle durdurmak', 'Yargının yasama yetkisi kullanmasını sağlamak', 'Halk oylamalarını yasaklamak ve Meclisi devre dışı bırakmak'], 'Katı (sert) anayasalar, temel düzenin geçici çoğunlukların isteğiyle kolayca değiştirilmesini önlemek için nitelikli çoğunluk arar.'),
  ('Merkezi yönetimin yerel yönetimler üzerinde sahip olduğu denetim yetkisine ne ad verilir ve bu yetki hiyerarşiden nasıl ayrılır?', 'İdari vesayet; kanunla sınırlıdır ve emir verme yetkisi içermez.', ['Hiyerarşi; sınırsızdır ve her işlemi değiştirme yetkisi verir.', 'Yetki genişliği; yalnız mahkemelerce kullanılır.', 'Yasama denetimi; Meclis tarafından kanun çıkarılarak kullanılır.'], 'İdari vesayet, ayrı tüzel kişiliğe sahip yerel yönetimler üzerinde kanunda öngörülen ölçüde yapılan denetimdir; hiyerarşideki emir ve talimat yetkisini içermez.'),
  ('Yerel yönetimlerin güçlendirilmesinin demokrasi açısından en önemli katkısı hangisidir?', 'Vatandaşların kendilerine en yakın düzeyde yönetime katılabilmesi', ['Seçimlerin tamamen kaldırılması', 'Merkezi yönetimin bütün görevlerini kaybetmesi', 'Yargı organlarının yerel yöneticilere bağlanması'], 'Yerellik ilkesiyle hizmetler halka en yakın birimce sunulur; bu, katılımı ve hesap verebilirliği artırır.'),
  ('İptal davası ile tam yargı davası arasındaki temel fark hangisidir?', 'İptal davası işlemi ortadan kaldırmayı, tam yargı davası zararı gidermeyi amaçlar.', ['İptal davası yalnız tacirlerce, tam yargı davası yalnız memurlarca açılır.', 'İptal davası adli yargıda, tam yargı davası Anayasa Mahkemesinde görülür.', 'İkisi de yalnız ceza davalarında kullanılan kanun yollarıdır.'], 'İptal davasında hukuka aykırı işlemin iptali, tam yargı davasında ise idarenin sebep olduğu zararın tazmini istenir.'),
  ('Kamu Denetçiliği Kurumunun kararlarının mahkeme kararlarından temel farkı nedir?', 'Bağlayıcı değil, tavsiye niteliğindedir.', ['Mahkeme kararlarından daha üstündür.', 'Yalnızca ceza davalarında uygulanır.', 'Cumhurbaşkanının onayıyla kanun hükmü kazanır ve herkesi bağlar.'], 'Ombudsman kurumları idareyi ikna ve tavsiye yoluyla denetler; kararları idare için hukuken bağlayıcı değildir.'),
  ('Türkiye\'de doğan ve yabancı ana-babasından dolayı hiçbir ülkenin vatandaşlığını doğumla kazanamayan bir çocuk Türk vatandaşlığını hangi esasa göre kazanır?', 'Doğum yeri esası', ['Soy bağı esası', 'Evlat edinme', 'Yetkili makam kararı'], '5901 sayılı Türk Vatandaşlığı Kanunu\'na göre Türkiye\'de doğan ve vatansız kalacak çocuklar doğumla Türk vatandaşı olur.'),
  ('Bir Türk vatandaşıyla evlenen yabancının Türk vatandaşlığını kazanmasına ilişkin hangisi doğrudur?', 'Evlilik kendiliğinden vatandaşlık kazandırmaz; en az üç yıllık evlilik ve başvuru gerekir.', ['Evlilik anında yabancı kendiliğinden Türk vatandaşı olur.', 'Yabancı eş hiçbir koşulda Türk vatandaşı olamaz.', 'Yabancı eş ancak on beş yıl Türkiye\'de oturursa başvurabilir.'], '5901 sayılı Kanun m.16\'ya göre evlilik doğrudan vatandaşlık kazandırmaz; en az üç yıldır evli olan ve evliliği devam eden yabancı başvurabilir.'),
  ('Anayasa\'ya göre eğitim ve öğrenim hakkı ile ilköğretimin niteliği arasındaki ilişki nasıl açıklanır?', 'İlköğretim kız ve erkek bütün vatandaşlar için zorunludur ve devlet okullarında parasızdır.', ['İlköğretim yalnızca kırsal bölgelerde zorunludur.', 'Eğitim yalnızca özel okullarda verilebilir.', 'İlköğretim isteğe bağlıdır ve her zaman ücretlidir.'], 'Anayasa m.42\'ye göre ilköğretim zorunludur ve devlet okullarında parasızdır; böylece eğitim hem hak hem ödev niteliği taşır.'),
  ('Seçme hakkının yanında seçilme hakkının da tanınmasının demokratik önemi nedir?', 'Vatandaşların yönetici olarak da siyasal sürece katılabilmesi', ['Seçimlerin daha az sıklıkla yapılması', 'Yalnızca zengin kişilerin aday olabilmesi', 'Oy kullanmanın zorunlu olmaktan çıkması ve katılımın azalması'], 'Seçilme hakkı, temsilcilerin toplumun her kesiminden gelebilmesini sağlayarak siyasal katılımı genişletir.'),
  ('Bir öğrenci, belediyenin park yapımı için ne kadar harcama yaptığını öğrenmek istiyor. Bu talebin dayanağı olan hak ve kanuna göre kurumun yanıt süresi kural olarak ne kadardır?', 'Bilgi edinme hakkı; 15 iş günü', ['Dilekçe hakkı; 90 gün', 'Basın özgürlüğü; 1 yıl', 'Hak arama hürriyeti; 6 ay'], '4982 sayılı Kanun\'a göre kurumlar başvurulara kural olarak 15 iş günü içinde yanıt verir; başka birimden görüş alınması gerekirse süre 30 iş gününe uzayabilir.'),
  ('Ölüm cezasının Türk hukukundan tamamen kaldırılması sürecine ilişkin hangisi doğrudur?', '2004 anayasa değişikliğiyle Anayasa\'daki ölüm cezası ifadeleri tamamen çıkarılmıştır.', ['Ölüm cezası 1924\'te kaldırılmıştır.', 'Ölüm cezası 1982 Anayasası\'nın ilk metninde yasaklanmıştır.', 'Ölüm cezası hiçbir zaman Türk hukukunda yer almamış, yalnız tartışılmıştır.'], '2002\'de barış zamanı için kanunla kaldırılan ölüm cezası, 2004 değişikliğiyle Anayasa\'dan tamamen çıkarıldı; m.38\'e "ölüm cezası ve genel müsadere cezası verilemez" hükmü eklendi.'),
  ('Devlet, bir otoyol yapımı için özel mülkiyetteki bir araziyi sahibinin rızası olmadan almak istiyor. Anayasa\'ya göre bunun koşulu nedir?', 'Gerçek karşılığının peşin ödenerek kamulaştırma yapılması', ['Arazinin bedelsiz olarak devlete geçmesi', 'Sahibinin rızasının noterle alınması zorunluluğu', 'Arazinin yalnızca kiralanabilmesi, kamulaştırma yasağı'], 'Anayasa m.46\'ya göre kamulaştırma, kamu yararının gerektirdiği hâllerde gerçek karşılığı peşin ödenmek şartıyla yapılabilir.'),
  ('Anayasa m.65\'te sosyal ve ekonomik hakların "malî kaynakların yeterliliği ölçüsünde" gerçekleştirileceğinin belirtilmesi neyi gösterir?', 'Bu hakların gerçekleşmesinin devletin ekonomik imkânlarıyla bağlantılı olduğunu', ['Bu hakların hiçbir zaman uygulanmayacağını', 'Bu hakların yalnız yabancılara tanındığını', 'Bu hakların ceza hukukuna ait olduğunu ve mahkemece verildiğini'], 'Pozitif statü hakları devletin kaynak ayırmasını gerektirdiğinden Anayasa, bu ödevlerin ekonomik istikrarı gözeterek ve mali kaynaklar ölçüsünde yerine getirileceğini belirtir.'),
  ('Bir kişi, yalnızca komşusunun manzarasını kapatmak amacıyla kendi arsasına işe yaramaz yüksek bir duvar örüyor. Bu davranış Medeni Kanun açısından nasıl değerlendirilir?', 'Hakkın kötüye kullanılması', ['İyi niyetin korunması', 'Kanuni temsil', 'Mülkiyetin kazanılması ve tapuya tescil'], 'TMK m.2\'ye göre bir hakkın, sırf başkasına zarar vermek için kullanılması açıkça kötüye kullanmadır ve hukuk düzenince korunmaz.'),
  ('Medeni Kanun m.3\'te iyi niyetin varlığının asıl olduğunun belirtilmesi uygulamada ne sonuç doğurur?', 'Kötü niyet iddia eden taraf bunu ispat etmek zorundadır.', ['İyi niyetli olduğunu her zaman kişinin kendisi ispatlar.', 'İyi niyet hiçbir zaman hukuki sonuç doğurmaz.', 'İyi niyet yalnızca ceza davalarında dikkate alınır ve hukuk davalarında aranmaz.'], 'TMK m.3\'e göre iyi niyet karinedir; aksini iddia eden, kötü niyeti ispat etmelidir.'),
  ('Mutlak haklar ile nispi haklar arasındaki fark hangi örnek ikiliyle doğru biçimde gösterilmiştir?', 'Mülkiyet hakkı mutlak, kira alacağı nispidir.', ['Kira alacağı mutlak, mülkiyet hakkı nispidir.', 'Her ikisi de mutlak haktır.', 'Her ikisi de yalnızca kamu hukukunda bulunan haklardır.'], 'Mutlak haklar herkese karşı ileri sürülebilir; nispi haklar ise yalnızca belirli kişiye, örneğin borçluya karşı ileri sürülebilir.'),
  ('Bir eylemin suç sayılabilmesi için gerekli unsurlar arasında aşağıdakilerden hangisi yer almaz?', 'Failin zengin olması', ['Kanunda tanımlanmış olması', 'Hukuka aykırı olması', 'Failin kast veya taksirle hareket etmesi'], 'Suçun unsurları; kanuni tanım, hukuka aykırılık ve kusurdur. Failin ekonomik durumu suçun varlığını etkilemez.'),
  ('Yangından kaçmak için başkasının kapısını kırarak eve sığınan kişinin durumu Türk Ceza Kanunu\'na göre hangi sebeple değerlendirilir?', 'Zorunluluk hâli', ['Meşru savunma', 'Haksız tahrik', 'Hakkın kullanılması'], 'TCK m.25/2\'ye göre ağır ve muhakkak bir tehlikeden kurtulmak için başka türlü korunma imkânı olmayan kişinin orantılı eylemi zorunluluk hâli sayılır.'),
  ('Tahkim ile arabuluculuk arasındaki temel fark hangisidir?', 'Hakem bağlayıcı karar verir, arabulucu ise karar vermez.', ['Arabulucu bağlayıcı karar verir, hakem vermez.', 'İkisi de yalnız ceza davalarında uygulanır.', 'İkisi de Anayasa Mahkemesinin bir dairesi olarak görev yapar.'], 'Tahkimde uyuşmazlık hakem kararıyla bağlayıcı biçimde çözülür; arabuluculukta çözüm tarafların anlaşmasına bağlıdır.'),
  ('1948 tarihli Soykırım Suçunun Önlenmesi ve Cezalandırılması Sözleşmesi\'nin uluslararası hukuka getirdiği temel yenilik nedir?', 'Belirli bir grubu yok etme amaçlı eylemleri uluslararası suç olarak tanımlaması', ['Devletlere savaş ilan etme hakkı vermesi', 'Sadece ekonomik yaptırımları düzenlemesi', 'Mülteci statüsünü ve sığınma başvurusu usulünü belirlemesi'], 'Sözleşme, ulusal, etnik, ırki veya dini bir grubu kısmen ya da tamamen yok etme kastıyla işlenen eylemleri uluslararası hukuka göre suç saymıştır.'),
  ('AİHM\'nin bir ihlal kararı vermesi hâlinde Türk hukukunda bu karar hangi sonucu doğurabilir?', 'İlgili kesinleşmiş davanın yeniden yargılanması talep edilebilir.', ['Türkiye\'deki ilgili kanun kendiliğinden yürürlükten kalkar.', 'Davayı gören hâkim otomatik olarak görevden alınır.', 'AİHM kararı Türk mahkemesinin yerine geçerek doğrudan infaz edilir ve sanık serbest kalır.'], 'Usul kanunlarında yapılan düzenlemelerle AİHM\'nin ihlal kararı, kesinleşmiş ceza ve hukuk davalarında yargılamanın yenilenmesi sebebi sayılmıştır.'),
  ('AİHM kararlarının uygulanmasının denetimi Avrupa Konseyinin hangi organınca yapılır?', 'Bakanlar Komitesi', ['Parlamenter Meclis', 'Venedik Komisyonu', 'Avrupa İnsan Hakları Komiseri ve sekreterlik'], 'AİHS m.46\'ya göre kesinleşen mahkeme kararlarının yerine getirilmesini Avrupa Konseyi Bakanlar Komitesi denetler.'),
  ('2004 anayasa değişiklikleriyle kaldırılan ve olağan yargı dışında özel bir yargı düzeni oluşturduğu gerekçesiyle eleştirilen mahkemeler hangileridir?', 'Devlet Güvenlik Mahkemeleri', ['Bölge idare mahkemeleri', 'Asliye hukuk mahkemeleri', 'Tüketici mahkemeleri ve iş mahkemeleri'], '2004 değişikliğiyle Anayasa m.143\'te düzenlenen Devlet Güvenlik Mahkemeleri kaldırılmıştır.'),
  ('Anayasa\'nın "Başlangıç" kısmında yer alan "hiçbir faaliyetin Türk millî menfaatlerinin ... karşısında korunma göremeyeceği" ifadesi hukuk düzeninde hangi işlevi görür?', 'Hakların yorumlanmasında ve sınırlanmasında yol gösterici bir ilke olması', ['Yalnız tarihsel bir anı olarak kalması', 'Seçim sistemini doğrudan belirlemesi', 'Cumhurbaşkanının görev süresini düzenlemesi'], 'Başlangıç kısmı Anayasa metnine dâhil olduğundan Anayasa Mahkemesi ve diğer yargı yerleri yorumda bu ilkeleri göz önünde bulundurur.'),
  ('1921 ve 1982 anayasaları karşılaştırıldığında kuvvetler ayrılığı bakımından hangi tespit doğrudur?', '1921\'de kuvvetler birliği, 1982\'de kuvvetler ayrılığı esas alınmıştır.', ['İkisi de kuvvetler birliğini benimsemiştir.', '1921\'de sert kuvvetler ayrılığı, 1982\'de kuvvetler birliği vardır.', 'İkisinde de yargı yetkisi doğrudan Cumhurbaşkanına verilmiştir.'], '1921 Anayasası yasama ve yürütmeyi TBMM\'de toplarken 1982 Anayasası yasama, yürütme ve yargıyı ayrı organlara vermiştir.'),
  ('Avukatlık, mühendislik ve hekimlik gibi meslek mensuplarının kurduğu barolar ve odalar Anayasa\'da hangi nitelikte düzenlenmiştir?', 'Kamu kurumu niteliğindeki meslek kuruluşları', ['Siyasi partiler', 'Özel şirketler', 'Baskı grubu niteliğinde sendikalar'], 'Anayasa m.135\'e göre kamu kurumu niteliğindeki meslek kuruluşları kanunla kurulur, organlarını üyeleri seçer ve siyasi faaliyette bulunamazlar.'),
  ('Mahkemenin verdiği alacak hükmünü borçlu ödemezse alacaklının izleyeceği yol hangisidir?', 'İcra dairesine başvurarak cebri icra istemek', ['Anayasa Mahkemesine bireysel başvuru yapmak', 'Dilekçe hakkıyla TBMM\'ye başvurmak', 'Kamu Denetçiliği Kurumundan karar istemek ve beklemek'], 'Mahkeme ilamının yerine getirilmesi icra daireleri aracılığıyla, gerekirse borçlunun malları haczedilerek sağlanır.'),
  ('Bir ceza davasında, yeterli delil bulunamadığı için sanık hakkında beraat kararı verilmiştir. Bu karar hangi ilkenin bir yansımasıdır?', 'Şüpheden sanık yararlanır ilkesi', ['Kanunların geriye yürümezliği', 'Kıyas yasağı', 'Ceza zamanaşımının kesilmesi ve durması'], 'Ceza muhakemesinde suçun işlendiği şüpheden uzak biçimde ispatlanamazsa sanık lehine karar verilir.'),
  ('Bir konuda TBMM\'nin bilgi edinmek amacıyla bir komisyon kurarak inceleme yapması hangi denetim yoludur?', 'Meclis araştırması', ['Meclis soruşturması', 'Genel görüşme', 'Yazılı soru önergesi'], 'Meclis araştırması, belli bir konuda bilgi edinmek için yapılan incelemedir; meclis soruşturması ise cezai sorumluluk araştırmasıdır.'),
  ('Toplumu ve devlet faaliyetlerini ilgilendiren belli bir konunun TBMM Genel Kurulunda görüşülmesine ne ad verilir ve bu yolun temel sonucu nedir?', 'Genel görüşme; görüşme sonunda yaptırım doğmaz.', ['Genel görüşme; hükümet düşer.', 'Gensoru; Cumhurbaşkanı görevden alınır.', 'Meclis soruşturması; ilgili bakan doğrudan cezalandırılır.'], 'Genel görüşme bir tartışma ve kamuoyunu bilgilendirme aracıdır; siyasi veya hukuki bir yaptırım doğurmaz.'),
  ('Olağanüstü hal kararının TBMM onayına sunulmasının anayasal amacı nedir?', 'Yürütmenin istisnai yetkisi üzerinde yasama denetimi kurmak', ['Kararın Anayasa Mahkemesince iptalini kolaylaştırmak', 'Seçimleri ertelemeyi zorunlu kılmak', 'Olağanüstü hali her durumda sınırsız süreli yapmak'], 'TBMM olağanüstü hal süresini kısaltabilir, uzatabilir veya kaldırabilir; bu, yürütmenin yetkisini yasama denetimine bağlar.'),
  ('Genel af ile özel af arasındaki farkı en iyi açıklayan ifade hangisidir?', 'Genel af TBMM\'nin kanunla yaptığı ve suç türlerine yönelik bir düzenlemedir; özel af belirli kişilere yöneliktir.', ['Genel af yalnız Cumhurbaşkanınca, özel af yalnız Anayasa Mahkemesince ilan edilir.', 'Genel af kişiye, özel af suç türüne yöneliktir.', 'İkisi de idare mahkemelerinin verdiği kararlardır.'], 'TBMM üye tamsayısının beşte üç çoğunluğuyla genel af ilan edebilir; özel af ise belirli kişilerin cezasını etkiler.'),
  ('TBMM\'nin seçimlerin yenilenmesine karar verebilmesi için Anayasa m.116\'ya göre hangi çoğunluk gerekir?', 'Üye tamsayısının beşte üçü', ['Toplantıya katılanların salt çoğunluğu', 'Üye tamsayısının dörtte biri', 'Üye tamsayısının üçte biri ve en az iki siyasi parti grubu'], 'Anayasa m.116\'ya göre TBMM üye tamsayısının beşte üç çoğunluğuyla seçimlerin yenilenmesine karar verebilir; bu durumda TBMM ve Cumhurbaşkanlığı seçimleri birlikte yapılır.'),
  ('Cumhurbaşkanlığının herhangi bir sebeple boşalması hâlinde Anayasa\'ya göre ne olur?', 'Kırk beş gün içinde seçim yapılır; bu sürede yardımcı vekâlet eder.', ['TBMM Başkanı görev süresinin sonuna kadar Cumhurbaşkanı olur.', 'Başbakan Cumhurbaşkanlığına geçer.', 'Anayasa Mahkemesi Başkanı bir yıl süreyle görev yapar.'], 'Anayasa m.106\'ya göre Cumhurbaşkanlığı boşalırsa kırk beş gün içinde seçim yapılır; seçilene kadar Cumhurbaşkanı yardımcısı vekâlet eder.'),
  ('İşkenceye karşı Avrupa Konseyi bünyesinde kurulan Avrupa İşkencenin Önlenmesi Komitesi\'nin (CPT) çalışma yöntemi hangisidir?', 'Tutulma yerlerini önceden haber vermeden ziyaret ederek önleyici denetim yapmak', ['İşkence yapanları doğrudan hapis cezasına çarptırmak', 'Devletler arası savaşlara son vermek', 'Yalnızca bireysel başvuruları yargılayıp tazminata hükmetmek'], 'CPT yargısal bir organ değildir; cezaevi ve karakol gibi yerleri ziyaret ederek raporlar hazırlar ve önleyici bir mekanizma işlevi görür.'),
  ('"Anayasal demokrasi" kavramının özünü en iyi açıklayan ifade hangisidir?', 'Seçilmiş çoğunluğun gücünün anayasa ve temel haklarla sınırlandırılması', ['Anayasanın yalnızca bir kez yazılıp hiç değiştirilmemesi', 'Bütün kararların halk oylamasıyla alınması', 'Anayasanın yürütme organı tarafından tek başına yazılması'], 'Anayasal demokrasi, halk egemenliği ile sınırlı iktidar fikrini birleştirir; çoğunluk anayasanın çizdiği sınırlar içinde yönetir.'),
  ('Bir sınıfta çoğunluk, bir öğrencinin farklı görüşte olduğu için sınıf etkinliklerine katılmasını yasaklamaya karar veriyor. Bu karar demokratik açıdan neden sorunludur?', 'Çoğunluk kararı azınlığın temel haklarını ortadan kaldıramaz.', ['Kararın oybirliğiyle alınmamış olması tek başına geçersizlik sebebidir.', 'Sınıflarda hiçbir zaman oylama yapılamaz.', 'Öğrencilerin görüş bildirme hakkı bulunmamaktadır.'], 'Demokrasi çoğunluğun yönetimidir ama çoğunluk, katılım ve ifade gibi temel hakları azınlıktan alamaz.'),
  ('Aynı konuyu düzenleyen genel bir kanun ile özel bir kanun arasında çatışma olduğunda hangi kural uygulanır?', 'Özel kanun genel kanuna göre öncelikle uygulanır.', ['Her zaman daha önce çıkan kanun uygulanır.', 'İki kanun da uygulanmaz, hâkim kendi görüşünü esas alır.', 'Genel kanun her durumda özel kanunu kaldırır ve tek başına uygulanır.'], 'Hukukta "özel hüküm genel hükümden önce gelir" ilkesi geçerlidir; ancak bu iki norm aynı basamaktaysa uygulanır.'),
  ('Ahlak kuralları ile hukuk kuralları arasındaki ilişkiye dair en doğru değerlendirme hangisidir?', 'Birçok hukuk kuralı ahlaki değerlerden beslenir, ancak her ahlak kuralı hukuk kuralı değildir.', ['Hukuk ve ahlak kuralları her konuda tamamen aynıdır.', 'Hukuk kuralları ahlakla hiçbir bağlantı taşımaz.', 'Ahlak kuralları devlet tarafından zorla uygulatılır.'], 'Hırsızlık yasağı gibi kurallar hem ahlaki hem hukukidir; ancak yalan söylememek gibi pek çok ahlak kuralı genel olarak hukuki yaptırıma bağlanmamıştır.'),
  ('Ayırt etme gücüne sahip bir küçüğün yasal temsilcisinin izni olmadan yapabileceği işlemlere örnek hangisidir?', 'Karşılıksız kazandırmaları, örneğin bir hediyeyi kabul etmek', ['Kredi sözleşmesi imzalamak', 'Ev satın almak', 'Kefil olmak ve borç senedi düzenlemek'], 'TMK m.16\'ya göre ayırt etme gücüne sahip küçükler karşılıksız kazanımları kabul edebilir ve kişiye sıkı sıkıya bağlı hakları kullanabilir.'),
  ('Ölen bir kişinin mirasçılarından bazılarının mirastan tamamen yoksun bırakılmasını engelleyen ve kanunla güvence altına alınan paya ne ad verilir?', 'Saklı pay', ['Vasiyet', 'Bağış', 'Mirasçılık belgesi ve tenkis'], 'TMK\'ya göre altsoy, ana-baba ve eş saklı paylı mirasçılardır; miras bırakan vasiyetle bu payları ihlal edemez.'),
  ('1924\'te şer\'iye mahkemelerinin kaldırılmasının hukuk düzenine etkisi en doğru nasıl değerlendirilir?', 'Yargıda birliği sağlayarak laik bir yargı düzeninin temelini attı.', ['Yargıyı tamamen yürütmeye bağladı.', 'Ceza davalarının sona ermesine yol açtı.', 'Osmanlı Kanun-i Esasi\'sini yeniden yürürlüğe koydu ve meşrutiyete dönüldü.'], 'Şer\'iye mahkemeleri kaldırılınca bütün davalar tek tip devlet mahkemelerinde görülmeye başlandı; bu, laik hukuk devriminin önemli adımlarındandır.'),
  ('Türkiye\'de 1950 genel seçimlerinin demokrasi tarihi açısından önemi nedir?', 'İktidarın ilk kez seçim yoluyla barışçıl biçimde el değiştirmesi', ['İlk kez kadınların oy kullanması', 'Cumhuriyetin bu seçimle ilan edilmesi', 'Anayasa Mahkemesinin bu seçimle kurulması ve ilk üyelerinin seçilmesi'], '14 Mayıs 1950 seçimlerinde Demokrat Parti kazanmış ve CHP iktidarı seçimle devretmiştir.'),
  ('Cumhuriyetin ilk yıllarındaki çok partili hayat denemelerinin kısa sürmesi hangi gerçekliği gösterir?', 'Demokratik kurumların yerleşmesinin toplumsal ve siyasal koşullara bağlı uzun bir süreç olduğunu', ['Türkiye\'de hiçbir zaman muhalefet partisi kurulmadığını', 'Muhalefet partilerinin anayasa tarafından açıkça yasaklandığını', 'Seçimlerin 1920\'lerde tamamen kaldırıldığını ve hiç yapılmadığını'], '1924 ve 1930 denemeleri kısa sürmüş, kalıcı çok partili hayata 1946\'da geçilebilmiştir; bu, demokrasinin aşamalı geliştiğini gösterir.'),
  ('1926 Türk Medeni Kanunu\'nun "iktibas" yoluyla hazırlanmasına yöneltilen eleştiriye karşı en güçlü savunma hangisidir?', 'Kanun zamanla toplumsal hayatı dönüştürerek benimsenmiş ve yargı kararlarıyla Türk toplumuna uyarlanmıştır.', ['Kanun hiçbir zaman uygulanmamıştır.', 'Kanun yalnızca yabancılar için hazırlanmıştır.', 'Kanun İsviçre\'de de hiç uygulanmamış bir taslaktı.'], 'İktibas edilen kanun, eğitim ve yargı içtihatlarıyla Türkiye\'ye özgü bir uygulama kazanmış, toplumsal değişimin aracı olmuştur.'),
  ('Bir öğrenci, okul yönetiminin hakkında verdiği disiplin cezasına itiraz etmek istiyor ancak kendisine savunma hakkı tanınmadan ceza verildiğini belirtiyor. Bu iddia en çok hangi ilkeyle ilgilidir?', 'Savunma hakkı ve hukuki güvence', ['Laiklik', 'Millî egemenlik', 'Kuvvetler ayrılığı ve yasama yetkisi'], 'Anayasa m.129\'a göre memurlar ve diğer kamu görevlileri hakkında savunma hakkı tanınmadan disiplin cezası verilemez; bu ilke idari işlemlerde de hukuki güvencenin gereğidir.'),
  ('Polis, bir kişiyi gece yarısı gözaltına almış ve ailesine haber verilmesine izin vermemiştir. Anayasa\'ya göre bu uygulamanın sorunlu yanı nedir?', 'Yakalanan kişinin durumu yakınlarına derhâl bildirilmelidir.', ['Gözaltı her durumda yasaktır.', 'Gözaltı kararını yalnızca belediye verebilir.', 'Gözaltına alınan kişi derhâl serbest bırakılmalıdır.'], 'Anayasa m.19\'a göre yakalanan veya tutuklanan kişinin durumu, kendisinin istemi dışındaki zorunlu hâller hariç, yakınlarına derhâl bildirilir.'),
  ('Bir mahkeme, sanığın anlamadığı bir dilde yargılama yapmış ve kendisine tercüman sağlamamıştır. Bu durum en doğru biçimde nasıl nitelenir?', 'Adil yargılanma hakkının ihlali', ['Mülkiyet hakkının ihlali', 'Seçme hakkının ihlali', 'Yasama sorumsuzluğunun ihlali'], 'AİHS m.6\'ya göre suçlanan herkes, mahkemede kullanılan dili anlamıyor veya konuşamıyorsa bir tercümanın yardımından ücretsiz yararlanma hakkına sahiptir.'),
  ('Bir televizyon kanalı, suçlanan ancak hakkında henüz karar verilmemiş bir kişiyi haberlerinde "katil" olarak nitelendirmektedir. Bu yayına ilişkin en doğru değerlendirme hangisidir?', 'Masumiyet karinesini zedelediği için hukuka aykırı bir yayın niteliği taşır.', ['Basın özgürlüğü kapsamında hiçbir sınırlamaya tabi değildir.', 'Kişinin suçlu olduğunu hukuken kesinleştirir.', 'Yargılamayı hızlandırdığı için hukuka uygundur.'], 'Masumiyet karinesi yalnız mahkemeleri değil, kamuoyunu yönlendiren açıklamaları da ilgilendirir; kesinleşmiş karar olmadan kişiyi suçlu gibi göstermek kişilik haklarını ihlal eder.'),
  ('Bir üniversite, öğrencilerin kampüste izinsiz bildiri dağıtmasını yasaklayan bir yönetmelik çıkarmıştır; yönetmeliğin dayanağı olan bir kanun hükmü yoktur. Bu yönetmeliğe yöneltilecek en güçlü hukuki itiraz hangisidir?', 'Temel hakların ancak kanunla sınırlanabileceği', ['Yönetmeliklerin Resmî Gazete\'de yayımlanamayacağı', 'Üniversitelerin hiçbir düzenleme yapamayacağı', 'Bildirilerin yalnız basın kuruluşlarınca dağıtılabileceği'], 'Anayasa m.13\'e göre temel hak ve özgürlükler ancak kanunla sınırlanabilir; kanuni dayanağı olmayan yönetmelikle ifade özgürlüğü kısıtlanamaz.'),
  ('Anayasa m.38\'e göre bir kişi sözleşmeden doğan borcunu ödeyemediği için hapsedilebilir mi?', 'Hayır, yalnızca sözleşmesel yükümlülüğü yerine getirememek özgürlükten alıkoyma sebebi olamaz.', ['Evet, her borç için hapis cezası verilir.', 'Evet, ancak borç belli miktarı aşıyorsa.', 'Hayır, ama kişinin seçme hakkı süresiz kaldırılır.'], 'Anayasa m.38\'e göre hiç kimse yalnızca sözleşmeden doğan bir yükümlülüğü yerine getirememesinden dolayı özgürlüğünden alıkonulamaz.'),
  ('İstinaf ile temyiz arasındaki temel fark hangisidir?', 'İstinafta olay ve hukuk birlikte incelenir, temyizde ise esas olarak hukuka uygunluk denetlenir.', ['İstinaf yalnız idari davalarda, temyiz yalnız ceza davalarında vardır.', 'Temyiz ilk derece mahkemesinde yapılır.', 'İstinaf Anayasa Mahkemesinde, temyiz Sayıştay\'da yapılır.'], 'Bölge adliye mahkemesi istinafta dosyayı olay ve hukuk yönünden yeniden inceleyebilir; Yargıtay ise temyizde kararın hukuka uygunluğunu denetler.'),
  ('2017 değişikliğinden önce Anayasa\'da yer alan "Cumhurbaşkanı seçilenin varsa partisi ile ilişiği kesilir" hükmüne ne olmuştur?', 'Kaldırılmıştır.', ['Daha da genişletilmiştir.', 'Milletvekillerine de uygulanır hâle gelmiştir.', 'Yalnız bakanlar için korunmuştur.'], '2017 değişikliğiyle bu hüküm kaldırılmış; Cumhurbaşkanının partisiyle ilişkisini sürdürebilmesinin önü açılmıştır.'),
  ('AİHS\'ye ek protokollerle güvenceye alınan haklar arasında hangisi yer alır?', 'Mülkiyetin korunması', ['Belirli bir dinin devlet dini olması', 'Anayasa değiştirme yetkisi', 'Seçimlerin her yıl yapılması'], 'AİHS\'ye Ek 1 No\'lu Protokol, mülkiyetin korunması, eğitim hakkı ve serbest seçim hakkını güvence altına alır.'),
  ('Parlamenter sistemde yürütmenin meclisi feshedebilmesi ile meclisin hükümeti düşürebilmesi arasındaki ilişki neyi sağlar?', 'Organlar arasında karşılıklı etkileşim ve denge', ['Yürütmenin mutlak üstünlüğünü', 'Meclisin yargıyı denetlemesini', 'Seçimlerin kaldırılmasını ve sürekli hükümeti'], 'Fesih ve güvensizlik oyu, parlamenter sistemin yumuşak kuvvetler ayrılığına dayanan karşılıklı denge mekanizmalarıdır.'),
  ('Temel hakların kötüye kullanılamayacağını düzenleyen Anayasa m.14\'ün amacı nedir?', 'Hakların demokratik düzeni ortadan kaldırmak için kullanılmasını önlemek', ['Bütün hakları askıya almak', 'Hakların yalnız devlet memurlarınca kullanılmasını sağlamak', 'Seçimleri ertelemek ve meclisi kapatmak'], 'Anayasa m.14\'e göre Anayasa\'daki hak ve hürriyetlerin hiçbiri, devletin bölünmez bütünlüğünü bozmayı ve demokratik ve laik Cumhuriyeti ortadan kaldırmayı amaçlayan faaliyetler biçiminde kullanılamaz.'),
  ('"Kanunlar herkese eşit uygulanıyor ama bazı kanunlar temel hakları ölçüsüz biçimde kısıtlıyor." Bu durum için en doğru değerlendirme hangisidir?', 'Kanuna bağlılık tek başına hukuk devleti için yeterli değildir; kanunların da hukuka ve anayasaya uygun olması gerekir.', ['Kanunlar eşit uygulandığı sürece içerikleri önemsizdir.', 'Hukuk devleti yalnız kanun sayısının fazla olmasıyla ölçülür.', 'Temel haklar kanunla her zaman ve sınırsızca kaldırılabilir.'], 'Biçimsel kanun devleti ile maddi hukuk devleti arasındaki fark budur; hukuk devleti kanunların da temel haklara ve anayasaya uygunluğunun denetlenmesini gerektirir.'),
];
